<script setup lang="ts">
import {ref, reactive, computed, onMounted, onUnmounted} from 'vue';
import {Layers, Inbox, ShieldCheck, BookOpen, Server, Activity, Settings, ArrowUpRight, Plus, Search, ArrowLeft, Play, Pause, Check, X, LogOut, RefreshCw, ChevronRight, Bell} from 'lucide-vue-next';
type Row=Record<string,any>;
const user=ref<Row|null>(null), page=ref('tickets'), busy=ref(false), error=ref(''), notice=ref(''), selected=ref<Row|null>(null);
const login=reactive({username:'employee',password:''}), rows=ref<Row[]>([]), approvals=ref<Row[]>([]), docs=ref<Row[]>([]), runs=ref<Row[]>([]), evaluations=ref<Row[]>([]), users=ref<Row[]>([]), notifications=ref<Row[]>([]);
const showNew=ref(false), query=ref(''), statusFilter=ref(''), comment=ref(''), mode=ref('mock'), trace=ref<Row|null>(null), sources=ref<Row[]>([]), knowledgeQuery=ref(''), preview=ref<Row|null>(null), business=ref<Row|null>(null), businessUser=ref(''), scenario=ref('normal'), supplement=ref('{}');
const settingsData=ref<Row>({chat:{},embedding:{},policy:{}}), profileStatus=reactive<Row>({}), evalLabel=ref('基线 v1'), evalSplit=ref('all'), approvalNotes=reactive<Row>({});
const compareIds=ref<string[]>([]);
const comparison=computed(()=>{const selected=evaluations.value.filter(e=>compareIds.value.includes(e.id));if(selected.length!==2)return null;const [a,b]=selected;return {a,b,rows:a.results.map((r:Row)=>({id:r.case_id,name:r.name,before:r,after:b.results.find((x:Row)=>x.case_id===r.case_id)}))};});
const fieldNames:Row={hours:'有效小时',resource:'申请权限',purpose:'申请用途',sku:'软件',employee_id:'申请人编号',device_id:'设备编号'};
const actionNames:Row={unlock_account:'解锁业务账号',grant_permission:'开通临时权限',assign_software:'分配软件授权'};
const form=reactive({title:'',description:'',kind:'account',resource:'VPN_ACCESS',hours:24,purpose:'',sku:'IDE_PRO'});
const nav=[{key:'tickets',label:'工单中心',icon:Inbox},{key:'approvals',label:'审批中心',icon:ShieldCheck},{key:'knowledge',label:'知识库',icon:BookOpen},{key:'business',label:'演示业务系统',icon:Server},{key:'runs',label:'运行与评测',icon:Activity},{key:'settings',label:'设置',icon:Settings}];
const labels:Row={pending:'待处理',processing:'处理中',waiting_info:'待补充',waiting_approval:'待审批',waiting_human:'待人工',waiting_confirmation:'待确认',closed:'已关闭',cancelled:'已取消',queued:'排队中',running:'运行中',paused:'已暂停',failed:'失败',completed:'已完成',approved:'已批准',rejected:'已拒绝',returned:'退回补充',superseded:'已失效',ready:'混合检索就绪',lexical_only:'仅全文检索',account:'账号解锁',permission:'临时权限',software:'软件授权',device:'设备报障',auto:'智能分类',employee:'员工',support:'IT 处理人员',approver:'部门审批人员',admin:'管理员',research:'查询证据',policy:'校验规则',approval:'等待审批',verify:'核验结果'};
const title=computed(()=>nav.find(n=>n.key===page.value)?.label||'工作台');
const metrics=computed(()=>[{label:'全部工单',value:rows.value.length},{label:'正在处理',value:rows.value.filter(t=>['pending','processing'].includes(t.status)).length},{label:'等待回应',value:rows.value.filter(t=>['waiting_approval','waiting_info','waiting_confirmation'].includes(t.status)).length},{label:'已解决',value:rows.value.filter(t=>t.status==='closed').length}]);
const filtered=computed(()=>rows.value.filter(t=>(!query.value||t.title.includes(query.value))&&(!statusFilter.value||t.status===statusFilter.value)));
let stream:EventSource|null=null, timer:ReturnType<typeof setInterval>|null=null;
const fmt=(d:string)=>new Date(d).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
async function api(path:string,method='GET',body?:unknown,refresh=true):Promise<any>{
  const response=await fetch('/api'+path,{method,credentials:'include',headers:body instanceof FormData?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:body instanceof FormData?body:JSON.stringify(body)});
  if(response.status===401&&refresh&& !path.startsWith('/auth/')){const r=await fetch('/api/auth/refresh',{method:'POST',credentials:'include'});if(r.ok)return api(path,method,body,false);user.value=null;}
  if(!response.ok){const data=await response.json().catch(()=>({detail:'服务暂不可用'}));throw new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));}
  return response.json();
}
async function task(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=String((e as Error).message);}finally{busy.value=false;}}
async function signIn(){await task(async()=>{user.value=await api('/auth/login','POST',login);login.password='';await load();});}
async function signOut(){await api('/auth/logout','POST');user.value=null;selected.value=null;stream?.close();}
async function load(){
  if(!user.value)return;
  const targetPage=page.value;
  if(targetPage==='tickets')rows.value=await api('/tickets');
  if(targetPage==='approvals')approvals.value=await api('/approvals');
  if(targetPage==='knowledge')docs.value=await api('/knowledge');
  if(targetPage==='business'){if(['admin','support'].includes(user.value.role))users.value=await api('/users');business.value=await api('/business'+(businessUser.value?'?employee_id='+businessUser.value:''));}
  if(targetPage==='runs'){runs.value=await api('/runs');if(['admin','support'].includes(user.value.role))evaluations.value=await api('/evaluations');}
  if(targetPage==='settings'){settingsData.value=await api('/settings');users.value=await api('/users');for(const kind of ['chat','embedding'])settingsData.value[kind]={base_url:'https://dashscope.aliyuncs.com/compatible-mode/v1',model:kind==='embedding'?'text-embedding-v4':'',timeout:45,max_tokens:1500,...settingsData.value[kind],api_key:''};}
}
async function navigate(key:string){page.value=key;selected.value=null;trace.value=null;stream?.close();error.value='';try{await load();}catch(e){if(page.value===key)error.value=(e as Error).message;}}
async function openTicket(id:string){selected.value=await api('/tickets/'+id);if(user.value?.role==='support')users.value=await api('/users');stream?.close();stream=new EventSource('/api/tickets/'+id+'/events');stream.onmessage=async()=>{if(selected.value?.ticket.id===id)selected.value=await api('/tickets/'+id);};}
function fields(){if(form.kind==='permission')return {resource:form.resource,hours:Number(form.hours),purpose:form.purpose};if(form.kind==='software')return {sku:form.sku,purpose:form.purpose};return {};}
async function create(){await task(async()=>{const t=await api('/tickets','POST',{title:form.title,description:form.description,kind:form.kind,fields:fields(),request_key:crypto.randomUUID()});showNew.value=false;await load();await openTicket(t.id);});}
async function mutate(action:string){await task(async()=>{const t=selected.value!.ticket;await api('/tickets/'+t.id+'/actions/'+action,'POST',{version:t.version,note:comment.value,fields:action==='comment'?JSON.parse(supplement.value):{}});comment.value='';supplement.value='{}';await openTicket(t.id);await load();});}
async function start(){await task(async()=>{const t=selected.value!.ticket;await api('/tickets/'+t.id+'/runs','POST',{version:t.version,mode:mode.value});await openTicket(t.id);});}
async function control(r:Row,action:string){await task(async()=>{await api('/runs/'+r.id+'/'+action,'POST');if(selected.value)await openTicket(selected.value.ticket.id);else await load();});}
async function decide(a:Row,decision:string){await task(async()=>{await api('/approvals/'+a.id+'/decision','POST',{decision,note:approvalNotes[a.id]||'',plan_digest:a.plan.digest});await load();notice.value='审批决定已保存';});}
async function upload(e:Event,documentId=''){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;await task(async()=>{const body=new FormData();body.append('file',file);if(documentId)body.append('document_id',documentId);await api('/knowledge/upload','POST',body);notice.value='资料已保存，后台正在解析';await load();});}
async function lookup(){await task(async()=>{sources.value=await api('/knowledge/search?q='+encodeURIComponent(knowledgeQuery.value));});}
function profilePayload(kind:string){const {has_key,...p}=settingsData.value[kind];return p;}
async function profileAction(kind:string,test=false){await task(async()=>{profileStatus[kind]='请求中…';try{const r=await api('/settings/'+kind+(test?'/test':''),test?'POST':'PUT',profilePayload(kind));profileStatus[kind]=test?(r.ok?'成功：':'失败：')+r.detail+`（${r.elapsed_ms} ms）`:'配置已加密保存';if(!test){settingsData.value[kind].api_key='';settingsData.value[kind].has_key=true;}}catch(e){profileStatus[kind]='失败：'+(e as Error).message;throw e;}});}
async function startEval(){await task(async()=>{await api('/evaluations','POST',{mode:mode.value,label:evalLabel.value,split:evalSplit.value});notice.value='评测已排队，结果逐条保存';await load();});}
onMounted(async()=>{try{user.value=await api('/auth/me');await load();}catch{}timer=setInterval(()=>{if(user.value&&!busy.value&&['knowledge','runs','approvals'].includes(page.value))load().catch(()=>{});},4000);});
onUnmounted(()=>{stream?.close();if(timer)clearInterval(timer);});
</script>

<template>
<div v-if="!user" class="login-shell">
  <section class="login-story"><div class="brand"><Layers :size="28"/> DeskFlow<span>企业 IT 服务台</span></div><div><p class="eyebrow">LESS WAITING. MORE FLOW.</p><h1>让每一个问题，<br>都有清晰的下一步。</h1><p>从员工的一次求助，到经过核验的处理结果。<br>把知识、审批与行动连接在同一个工作台。</p><div class="flow-preview"><span>提出问题</span><ChevronRight/><span>核对与审批</span><ChevronRight/><span>解决问题</span></div></div><small>DESKFLOW / SERVICE DESK AGENT · 01</small></section>
  <section class="login-panel"><div><p class="eyebrow">WELCOME BACK</p><h2>登录工作台</h2><p class="muted">使用你的演示账号继续</p><form @submit.prevent="signIn"><label>用户名<input v-model="login.username" autocomplete="username" required placeholder="employee / support / approver / admin"></label><label>密码<input v-model="login.password" autocomplete="current-password" type="password" required></label><p v-if="error" class="error">{{error}}</p><button class="primary wide" :disabled="busy">{{busy?'正在登录…':'登录 DeskFlow'}}<ArrowUpRight :size="18"/></button></form><p class="help">首次登录凭据位于项目 data/demo-credentials.json。<br>演示业务与平台登录账号相互独立。</p></div></section>
</div>
<div v-else class="app-shell">
  <aside class="sidebar"><div class="brand"><Layers/> DeskFlow</div><p class="workspace-label">企业 IT 工作空间</p><nav><button v-for="item in nav.filter(n=>n.key!=='settings'||user?.role==='admin')" :key="item.key" :class="{active:page===item.key}" @click="navigate(item.key)"><component :is="item.icon" :size="19"/>{{item.label}}<span v-if="item.key==='tickets'" class="nav-count">{{rows.length||'·'}}</span></button></nav><div class="side-note"><span class="live-dot"></span> 独立演示环境<p>业务操作可核验<br>每一步都有记录</p></div><div class="identity"><div class="avatar">{{user.name[0]}}</div><div><strong>{{user.name}}</strong><small>{{labels[user.role]}}</small></div><button class="icon" title="退出登录" @click="signOut"><LogOut :size="17"/></button></div></aside>
  <main><header class="topbar"><span>工作空间 <ChevronRight :size="14"/> {{title}}</span><div><span class="environment">DEMO</span><button class="icon" aria-label="站内通知" @click="task(async()=>{notifications=await api('/notifications')})"><Bell :size="19"/></button><span class="date">{{new Date().toLocaleDateString('zh-CN')}}</span></div></header>
    <div class="content"><div v-if="error" class="banner error">{{error}}<button class="icon" @click="error=''">×</button></div><div v-if="notice" class="banner success">{{notice}}</div><div v-if="notifications.length" class="card"><div class="row"><h3>站内通知</h3><button class="icon" @click="notifications=[]"><X/></button></div><button v-for="n in notifications.slice(0,8)" :key="n.id" class="notification" @click="page='tickets';openTicket(n.ticket_id);notifications=[]">{{n.data.text||n.data.label||labels[n.data.status]||'工单有新进展'}} <small>{{fmt(n.created_at)}}</small></button></div>
    <template v-if="page==='tickets'&&!selected"><div class="page-heading"><div><p class="eyebrow">SERVICE DESK</p><h1>工单中心<span class="heading-dot">.</span></h1><p class="muted">让处理过程透明，让每一次回应有据可依。</p></div><button class="primary" @click="showNew=true"><Plus :size="18"/>新建工单</button></div><div class="metrics"><div v-for="(m,i) in metrics" :key="m.label" class="metric"><span>{{m.label}}</span><strong>{{String(m.value).padStart(2,'0')}}</strong><span class="metric-index">0{{i+1}}</span></div></div><section class="card ticket-card"><div class="toolbar"><div class="tabs"><button v-for="s in ['', 'pending','waiting_approval','waiting_confirmation','closed']" :class="{chosen:statusFilter===s}" @click="statusFilter=s">{{s?labels[s]:'全部工单'}}</button></div><div class="search"><Search :size="16"/><input v-model="query" placeholder="搜索工单标题"></div></div><div class="table-wrap"><table><thead><tr><th>工单 / 问题</th><th>类型</th><th>状态</th><th>申请人</th><th>更新时间</th><th></th></tr></thead><tbody><tr v-for="t in filtered" :key="t.id" @click="task(()=>openTicket(t.id))"><td><strong>{{t.title}}</strong><small># {{t.id.slice(0,8).toUpperCase()}}</small></td><td>{{labels[t.kind]}}</td><td><span :class="['badge',t.status]">{{labels[t.status]}}</span></td><td>{{t.owner_name}}</td><td class="muted">{{fmt(t.updated_at)}}</td><td><ArrowUpRight :size="17"/></td></tr></tbody></table></div><div v-if="!filtered.length" class="empty"><Inbox :size="36"/><h3>从第一个问题开始</h3><p>提交账号、权限、软件或设备问题，跟踪完整处理进度。</p><button class="secondary" @click="showNew=true">创建工单</button></div><footer>{{filtered.length}} 个工单<span>已按最近更新排序</span></footer></section></template>
    <template v-if="page==='tickets'&&selected"><button class="back" @click="selected=null;stream?.close();load()"><ArrowLeft :size="16"/>返回工单列表</button><div class="page-heading"><div><p class="eyebrow"># {{selected.ticket.id.slice(0,8).toUpperCase()}}</p><h1>{{selected.ticket.title}}</h1><p class="muted">{{selected.ticket.owner_name}} · {{labels[selected.ticket.kind]}} · {{fmt(selected.ticket.created_at)}}</p></div><span :class="['badge',selected.ticket.status]">{{labels[selected.ticket.status]}}</span></div><div class="detail-grid"><section><div class="card"><h3>问题描述</h3><p class="pre">{{selected.ticket.description}}</p><div v-if="Object.keys(selected.ticket.fields).length" class="field-grid"><div v-for="(v,k) in selected.ticket.fields"><small>{{fieldNames[k]||k}}</small><strong>{{v}}</strong></div></div></div><div class="card timeline"><h3>处理记录</h3><article v-for="c in selected.comments" :key="c.id"><span class="timeline-dot"></span><div class="row"><strong>{{c.author_name}}</strong><small>{{fmt(c.created_at)}}</small></div><p class="pre">{{c.body}}</p><details v-for="s in c.citations" :key="s.id"><summary>[{{s.citation}}] {{s.document}} · v{{s.version}}</summary><p class="pre">{{s.text}}</p><small>{{JSON.stringify(s.location)}}</small></details></article><p v-if="!selected.comments.length" class="muted">尚无处理记录。可以发起分析，或等待 IT 人员接单。</p></div><div class="card"><h3>补充信息 / 人工处理结果</h3><textarea v-model="comment" placeholder="描述新的情况，或填写实际维修结果…"></textarea><details><summary>补充结构化参数</summary><p class="help">例如 {"resource":"VPN_ACCESS","purpose":"出差办公","hours":24}</p><textarea v-model="supplement" rows="2"></textarea></details><div class="actions"><button class="secondary" :disabled="busy" @click="mutate('comment')">发送补充</button><button v-if="user.role==='support'" class="primary" @click="mutate('resolve')">记录结果，等待确认</button><button v-if="selected.ticket.status==='waiting_confirmation'" class="primary" @click="mutate('confirm')"><Check :size="16"/>确认已解决</button><button class="text-button" @click="mutate('reopen')">重新打开</button></div></div></section><aside><div class="card"><p class="eyebrow">AGENT WORKFLOW</p><h3>处理控制</h3><div class="segmented"><button :class="{chosen:mode==='mock'}" @click="mode='mock'">模拟流程</button><button :class="{chosen:mode==='real'}" @click="mode='real'">真实模型</button></div><p class="help">{{mode==='mock'?'用于演示与回归，不调用大模型。':'使用管理员配置的模型，调用会产生 API 费用。'}}</p><button class="primary wide" :disabled="busy" @click="start"><Play :size="16"/>开始 / 重新分析</button><div v-if="selected.runs[0]" class="run-status"><div class="row"><span>{{labels[selected.runs[0].status]}}</span><small>{{labels[selected.runs[0].phase]||selected.runs[0].phase}}</small></div><p class="help">{{selected.runs[0].rounds}} 轮模型 · {{selected.runs[0].tool_calls}} 次工具调用</p><p v-if="selected.runs[0].error" class="error">{{selected.runs[0].error}}</p><button v-if="['running','queued'].includes(selected.runs[0].status)" class="secondary" @click="control(selected.runs[0],'pause')">暂停</button><button v-if="['paused','failed'].includes(selected.runs[0].status)" class="secondary" @click="control(selected.runs[0],'resume')">从断点继续</button></div><hr><div class="actions"><button v-if="user.role==='support'" class="secondary" @click="mutate('takeover')">人工接管</button><button class="text-button danger" @click="mutate('cancel')">取消工单</button></div><details v-if="user.role==='support'"><summary>转派给处理人员</summary><div class="chips"><button v-for="person in users.filter(x=>x.role==='support'&&x.active)" @click="task(async()=>{await api('/tickets/'+selected!.ticket.id+'/actions/assign','POST',{version:selected!.ticket.version,assignee_id:person.id});await openTicket(selected!.ticket.id)})">{{person.name}}</button></div></details></div><div v-for="p in selected.plans" :key="p.id" class="card"><h3>操作方案</h3><p>{{p.reason}}</p><dl><dt>动作</dt><dd>{{actionNames[p.action]||p.action}}</dd><dt>审批</dt><dd>{{p.approval?labels[p.approval.status]:'策略允许自动执行'}}</dd><dt v-if="p.operation">结果核验</dt><dd v-if="p.operation">{{p.operation.verified?'已验证':'尚未验证'}}</dd></dl><details><summary>参数与原始回执</summary><pre>{{JSON.stringify({params:p.params,operation:p.operation},null,2)}}</pre></details></div></aside></div></template>
    <template v-if="page==='approvals'"><div class="page-heading"><div><p class="eyebrow">HUMAN IN THE LOOP</p><h1>审批中心<span class="heading-dot">.</span></h1><p class="muted">确认具体变更后，Agent 才会继续执行。</p></div></div><div class="cards"><article v-for="a in approvals" :key="a.id" class="card"><div class="row"><h3>{{a.ticket.title}}</h3><span :class="['badge',a.status]">{{labels[a.status]||a.status}}</span></div><p>{{a.plan.reason}}</p><div class="field-grid"><div v-for="(v,k) in a.plan.params"><small>{{fieldNames[k]||k}}</small><strong>{{v}}</strong></div></div><p class="help">有效至 {{fmt(a.expires_at)}} · {{a.ticket.department}}</p><details><summary>知识依据</summary><p v-for="s in a.plan.evidence" class="pre">{{s.document}} v{{s.version}}：{{s.text}}</p></details><template v-if="a.status==='pending'&&user.role==='approver'&&a.ticket.owner_id!==user.id"><input v-model="approvalNotes[a.id]" placeholder="审批意见"><div class="actions"><button class="primary" :disabled="busy" @click="decide(a,'approved')">批准执行</button><button class="secondary" @click="decide(a,'returned')">退回补充</button><button class="text-button danger" @click="decide(a,'rejected')">拒绝</button></div></template></article></div><div v-if="!approvals.length" class="empty card"><ShieldCheck :size="36"/><h3>暂无待处理审批</h3><p>权限与软件授权方案会出现在这里。</p></div></template>
    <template v-if="page==='knowledge'"><div class="page-heading"><div><p class="eyebrow">KNOWLEDGE & EVIDENCE</p><h1>知识库<span class="heading-dot">.</span></h1><p class="muted">制度有来源，历史回答有版本。</p></div><label v-if="['admin','support'].includes(user.role)" class="primary upload"><Plus :size="18"/>导入资料<input type="file" accept=".md,.txt,.docx,.pdf" @change="upload($event)"></label></div><div class="card"><div class="row"><input v-model="knowledgeQuery" placeholder="试试：临时权限最多可以申请多久？" @keyup.enter="lookup"><button class="primary" :disabled="busy" @click="lookup">检索预览</button></div><article v-for="s in sources" class="source"><strong>{{s.document}} · v{{s.version}}</strong><p class="pre">{{s.text}}</p><small>{{s.warning||'混合检索'}} · {{JSON.stringify(s.location)}}</small></article></div><div class="cards"><article v-for="d in docs" :key="d.id" class="card"><div class="row"><BookOpen :size="20"/><h3>{{d.name}}</h3></div><div v-for="v in d.versions" class="version"><div class="row"><span>版本 {{v.number}} {{d.active_version_id===v.id?'· 当前有效':''}}</span><span :class="['badge',v.status]">{{labels[v.status]||v.status}}</span></div><p v-if="v.error" class="help">{{v.error}}</p><div class="actions"><button class="secondary" @click="task(async()=>{preview=await api('/knowledge/versions/'+v.id)})">查看分片</button><button v-if="['admin','support'].includes(user.role)" class="text-button" @click="task(async()=>{await api('/knowledge/versions/'+v.id+'/retry','POST');await load()})">重新入库</button></div></div><label v-if="['admin','support'].includes(user.role)" class="text-button upload">上传更新版本<input type="file" accept=".md,.txt,.docx,.pdf" @change="upload($event,d.id)"></label></article></div></template>
    <template v-if="page==='business'"><div class="page-heading"><div><p class="eyebrow">BUSINESS STATE</p><h1>演示业务系统<span class="heading-dot">.</span></h1><p class="muted">查看操作前后的真实数据库状态。</p></div><button class="secondary" @click="task(load)"><RefreshCw :size="16"/>刷新状态</button></div><div v-if="users.length" class="chips"><button v-for="u in users" :class="{chosen:businessUser===u.id}" @click="businessUser=u.id;task(load)">{{u.name}}</button></div><div v-if="business" class="detail-grid"><section><div class="card"><h3>{{business.employee.name}} · 业务账号</h3><div class="field-grid"><div><small>在职状态</small><strong>{{business.employee.active?'在职':'停用'}}</strong></div><div><small>账号状态</small><strong>{{business.employee.locked?'已锁定':'可登录'}}</strong></div><div><small>锁定原因</small><strong>{{business.employee.lock_reason||'无'}}</strong></div><div><small>账号类型</small><strong>{{business.employee.privileged?'特权账号':'普通账号'}}</strong></div></div></div><div class="card"><h3>权限与软件授权</h3><p v-if="!business.employee.permissions.length&&!business.employee.licenses.length" class="muted">暂无授权</p><p v-for="g in business.employee.permissions">{{g.resource}} · {{g.active?'有效':'已失效'}} · {{fmt(g.expires_at)}}</p><span v-for="s in business.employee.licenses" class="badge ready">{{s}}</span><hr><div v-for="s in business.software" class="row"><span>{{s.name}}</span><strong>{{s.available}} / {{s.capacity}} 剩余</strong></div></div></section><aside><div class="card"><h3>本人设备</h3><p v-for="d in business.employee.devices">{{d.name}}<small class="block">{{d.id}}</small></p></div><div v-if="user.role==='admin'" class="card"><h3>初始化演示场景</h3><p class="help">仅更新选中演示员工的账号状态，保留授权和历史回执。</p><div class="chips"><button v-for="s in ['normal','security_lock','inactive','privileged','unlocked']" :class="{chosen:scenario===s}" @click="scenario=s">{{({normal:'登录失败锁定',security_lock:'安全锁定',inactive:'停用',privileged:'特权账号',unlocked:'正常登录'} as Row)[s]}}</button></div><button class="secondary wide" @click="task(async()=>{await api('/business/scenario','POST',{employee_id:business!.employee.id,scenario});await load()})">应用场景</button></div></aside></div></template>
    <template v-if="page==='runs'"><div class="page-heading"><div><p class="eyebrow">OBSERVE & EVALUATE</p><h1>运行与评测<span class="heading-dot">.</span></h1><p class="muted">从工具调用到最终业务状态，逐步核验。</p></div></div><section v-if="user.role==='admin'" class="card"><h3>启动固定任务评测</h3><p class="help">30 个标注任务，20 个开发样例 / 10 个保留验证样例。每个样例使用独立演示员工及软件名额。</p><div class="row wrap"><input v-model="evalLabel" placeholder="版本标签"><div class="segmented"><button :class="{chosen:mode==='mock'}" @click="mode='mock'">模拟流程</button><button :class="{chosen:mode==='real'}" @click="mode='real'">真实模型</button></div><div class="segmented"><button v-for="s in ['all','dev','holdout']" :class="{chosen:evalSplit===s}" @click="evalSplit=s">{{({all:'全部',dev:'开发集',holdout:'保留集'} as Row)[s]}}</button></div><button class="primary" :disabled="busy" @click="startEval">开始评测</button></div></section><div class="cards"><article v-for="e in evaluations" class="card"><label class="inline"><input type="checkbox" :value="e.id" v-model="compareIds" :disabled="compareIds.length>=2&&!compareIds.includes(e.id)">加入对比</label><div class="row"><h3>{{e.label}}</h3><span class="badge">{{e.mode==='mock'?'模拟流程':'真实模型'}} · {{labels[e.status]}}</span></div><div class="score">{{e.summary.passed||0}}<small> / {{e.summary.completed||0}} 已完成</small></div><p class="help">{{e.summary.note}}</p><a :href="'/api/evaluations/'+e.id+'/report'" class="text-button">导出 Markdown 报告 ↗</a><details><summary>逐条结果</summary><p v-for="r in e.results">{{r.passed?'✓':'×'}} {{r.name}} · {{labels[r.actual]||r.actual}}<small v-if="r.error" class="error block">{{r.error}}</small></p></details></article></div><div v-if="comparison" class="card"><h3>{{comparison.a.label}} → {{comparison.b.label}}</h3><p class="help">{{comparison.a.mode}} / {{comparison.b.mode}} · {{comparison.a.summary.dataset_hash===comparison.b.summary.dataset_hash?'相同任务集':'任务集版本不同'}}。请同时检查资料版本与运行模式，不将环境差异归因于模型。</p><table><thead><tr><th>任务</th><th>前一版本</th><th>后一版本</th></tr></thead><tbody><tr v-for="c in comparison.rows"><td>{{c.name}}</td><td>{{c.before.passed?'通过':'未通过'}}</td><td>{{c.after?(c.after.passed?'通过':'未通过'):'尚未完成'}}</td></tr></tbody></table></div><div class="card"><h3>最近运行</h3><table><thead><tr><th>运行</th><th>模式</th><th>状态</th><th>模型 / 工具</th><th></th></tr></thead><tbody><tr v-for="r in runs" @click="task(async()=>{trace=await api('/runs/'+r.id+'/trace')})"><td>{{r.id.slice(0,8)}}<small>{{fmt(r.created_at)}}</small></td><td>{{r.mode==='mock'?'模拟流程':'真实模型'}}</td><td><span :class="['badge',r.status]">{{labels[r.status]}}</span></td><td>{{r.rounds}} 轮 / {{r.tool_calls}} 次</td><td><ArrowUpRight :size="16"/></td></tr></tbody></table></div></template>
    <template v-if="page==='settings'"><div class="page-heading"><div><p class="eyebrow">WORKSPACE SETTINGS</p><h1>设置<span class="heading-dot">.</span></h1><p class="muted">模型与密钥独立配置，仅在本项目使用。</p></div></div><div class="cards"><section v-for="kind in ['chat','embedding']" class="card"><h3>{{kind==='chat'?'对话模型':'Embedding 向量模型'}}</h3><p class="help">{{kind==='chat'?'使用支持流式输出与 Tool Calling 的兼容接口。':'统一使用 1024 维向量；更换模型后需要重新入库。'}}</p><label>Base URL<input v-model="settingsData[kind].base_url"></label><label>模型 ID<input v-model="settingsData[kind].model"></label><label>API Key<input type="password" v-model="settingsData[kind].api_key" :placeholder="settingsData[kind].has_key?'已加密保存，留空保留':'填写本项目独立密钥'" autocomplete="new-password"></label><details v-if="kind==='chat'"><summary>Prompt 与版本</summary><label>版本<input v-model="settingsData[kind].prompt_version"></label><textarea v-model="settingsData[kind].prompt" rows="6"></textarea></details><p v-if="profileStatus[kind]" class="test-result">{{profileStatus[kind]}}</p><div class="actions"><button class="secondary" :disabled="busy" @click="profileAction(kind,true)">测试连接</button><button class="primary" :disabled="busy" @click="profileAction(kind)">保存配置</button></div></section></div><section class="card"><h3>运行预算与业务策略</h3><div class="form-grid"><label>每次最多模型轮次<input type="number" v-model.number="settingsData.policy.max_rounds" min="1" max="50"></label><label>每次最多工具调用<input type="number" v-model.number="settingsData.policy.max_tools" min="1" max="100"></label><label>临时权限最长小时<input type="number" v-model.number="settingsData.policy.max_permission_hours" min="1" max="168"></label><label>审批有效小时<input type="number" v-model.number="settingsData.policy.approval_hours" min="1" max="72"></label></div><button class="primary" @click="task(async()=>{await api('/policy','PUT',settingsData.policy);notice='策略已保存；业务规则变化会使旧方案需要重新审批'})">保存策略</button></section><section class="card"><h3>用户与角色</h3><div v-for="u in users" class="user-edit"><input v-model="u.name"><input v-model="u.department"><select v-model="u.role"><option v-for="r in ['employee','support','approver','admin']" :value="r">{{labels[r]}}</option></select><label class="inline"><input type="checkbox" v-model="u.active">启用</label><button class="secondary" @click="task(async()=>{await api('/users/'+u.id,'PUT',{name:u.name,department:u.department,role:u.role,active:u.active});notice='用户已更新'})">保存</button></div></section></template>
    <footer class="page-footer">DESKFLOW · 企业 IT 服务台<span>可追踪 · 可审批 · 可核验</span></footer>
    </div>
  </main>
</div>
<div v-if="showNew" class="overlay" @click.self="showNew=false"><form class="modal" @submit.prevent="create"><div class="row"><div><p class="eyebrow">NEW REQUEST</p><h2>有什么可以帮你？</h2></div><button type="button" class="icon" @click="showNew=false"><X/></button></div><div class="chips"><button type="button" v-for="k in ['account','permission','software','device','auto']" :class="{chosen:form.kind===k}" @click="form.kind=k">{{labels[k]}}</button></div><label>工单标题<input v-model="form.title" required minlength="2" maxlength="200" placeholder="例如：业务账号因多次登录失败被锁定"></label><label>问题描述<textarea v-model="form.description" required minlength="2" rows="3" placeholder="请说明问题现象、发生时间及已尝试的方法"></textarea></label><template v-if="form.kind==='permission'"><label>申请权限<div class="chips"><button type="button" v-for="r in ['VPN_ACCESS','DEV_READONLY']" :class="{chosen:form.resource===r}" @click="form.resource=r">{{r==='VPN_ACCESS'?'远程办公 VPN':'开发资源只读'}}</button></div></label><label>有效期（小时）<input type="number" v-model.number="form.hours" min="1" max="168"></label></template><label v-if="form.kind==='software'">软件<div class="chips"><button type="button" v-for="s in ['IDE_PRO','DIAGRAM_TOOL']" :class="{chosen:form.sku===s}" @click="form.sku=s">{{s==='IDE_PRO'?'开发工具专业版':'流程图工具'}}</button></div></label><label v-if="['permission','software'].includes(form.kind)">申请用途<input v-model="form.purpose" placeholder="说明业务用途"></label><p v-if="error" class="error">{{error}}</p><button class="primary wide" :disabled="busy">{{busy?'正在提交…':'提交工单'}}<ArrowUpRight :size="17"/></button></form></div>
<div v-if="preview||trace" class="overlay" @click.self="preview=null;trace=null"><section class="modal large"><div class="row"><h2>{{preview?'资料分片':'执行轨迹'}}</h2><button class="icon" @click="preview=null;trace=null"><X/></button></div><template v-if="preview"><article v-for="c in preview.chunks" class="source"><strong>片段 {{c.ordinal+1}}</strong><p class="pre">{{c.text}}</p><small>{{JSON.stringify(c.location)}}</small></article><p v-if="!preview.chunks.length" class="muted">尚未生成分片，请检查解析状态。</p></template><template v-if="trace"><p class="help">{{trace.run.mode==='mock'?'模拟流程，未调用真实模型':'真实模型运行'}} · {{labels[trace.run.status]}}</p><article v-for="e in trace.events" class="source"><div class="row"><strong>{{e.data.label||e.data.name||e.kind}}</strong><small>{{fmt(e.created_at)}}</small></div><p>{{e.data.text||e.data.summary||e.data.message}}</p><details><summary>输入、输出与证据</summary><pre>{{JSON.stringify(e.data,null,2)}}</pre></details></article></template></section></div>
</template>
